def process(sunspotPeaks1960to2020) -> pd.DataFrame:
    import pandas as pd

    df = sunspotPeaks1960to2020.copy()

    max_years = df.loc[df['type'] == 'max', 'year'].sort_values().astype(int).tolist()
    min_years = df.loc[df['type'] == 'min', 'year'].sort_values().astype(int).tolist()

    def avg_diff(years):
        if len(years) < 2:
            return None
        diffs = [b - a for a, b in zip(years[:-1], years[1:])]
        return sum(diffs) / len(diffs)

    avg_max = avg_diff(max_years)
    avg_min = avg_diff(min_years)

    avg_period = None
    if avg_max is not None and avg_min is not None:
        avg_period = (avg_max + avg_min) / 2
    elif avg_max is not None:
        avg_period = avg_max
    elif avg_min is not None:
        avg_period = avg_min

    return pd.DataFrame([{
        'avgPeriodYears': avg_period,
        'avgFromMaxima': avg_max,
        'avgFromMinima': avg_min,
        'nMax': len(max_years),
        'nMin': len(min_years),
        # store as strings to avoid LIST-typed column issues in the runtime
        'maxYears': ', '.join(map(str, max_years)),
        'minYears': ', '.join(map(str, min_years)),
    }])
